    });
  }

  cancelEdit(id: string): void {
    delete this.editing[id];
    delete this.editBuffer[id];
  }

  deleteAirport(id: string): void {
    this.adminSvc.deleteAirport(id).subscribe({
      next: () => this.airports = this.airports.filter(a => a._code !== id),
      error: err => alert('Errore eliminazione aeroporto')
    });
  }*/
}
<div class="admin-container">

  <!-- ✉️ INVITO COMPAGNIA -->
  <section class="card">
    <h2>Invita Compagnia Aerea</h2>
    <form [formGroup]="inviteForm" (ngSubmit)="inviteCompany()">
        <input formControlName="_signature" placeholder="Signature" />
        <input formControlName="username" placeholder="Username" />
        <input formControlName="name" placeholder="Nome compagnia" />
        <input formControlName="mail" placeholder="Email amministratore" />
        <input formControlName="passportID" placeholder="passport ID" />
        <input formControlName="password" placeholder="Password" />
        <button type="submit" [disabled]="inviteForm.invalid">Invita</button>
    </form>
  </section>

  <!-- 🛫 GESTIONE AEROPORTI -->
   <!--
